-- Seed demo-anixe (B2B Enterprise Showcase — 1:1 ANIXE portal)
INSERT INTO public.pages (slug, theme, color_preset, content, user_id, trial_blocked_at, billing_failed_at, billing_plan)
VALUES (
  'demo-anixe',
  'custom',
  'dark_gold',
  '{"theme_type":"cinematic","design":{"palette":"dark_gold","accent_color":"#58c1e9","bg_color":"#071739","font_theme":"modern_display"},"meta":{"title":"ANIXE | Growing Digital Travel & Commerce","description":"Leading travel technology provider specialized in third-party hotel supplier aggregation, high-speed cache data exports, Resfinity IBE, and automated hotel mapping."},"pl":{"settings":{"business_name":"ANIXE Polska Sp. z o.o.","city":"Wrocław","subscription":{"plan":"tier1","payment_completed":true,"trial_started_at":"2026-09-01T10:00:00.000Z"},"is_demo_catalog":true},"blocks":[{"id":"nav_mega","type":"mega_navbar","data":{"brand_name":"ANIXE","brand_tagline":"Growing Digital Travel & Commerce","cta_text":"Book a Demo","cta_url":"#contact","menu_groups":[{"id":"solutions","label":"Solutions","items":[{"title":"Airlines","desc":"Over 20 years covering web IBE, mid/back office, and mobile apps","href":"#solutions","icon":"✈️"},{"title":"Tour Operators","desc":"Agency portal, cache data conversion, accelerated search, and yield rules","href":"#solutions","icon":"🏖️"},{"title":"Online Travel Agencies","desc":"3rd party hotel aggregation, load management, and sub-second responses","href":"#solutions","icon":"💻"}]},{"id":"products","label":"What We Do","items":[{"title":"Hotel Dynamic Sourcing","desc":"More destinations, better prices, and higher profit with Resfinity","href":"#products","icon":"🌐"},{"title":"Hotel & Room Mapping","desc":"Automated AI mapping of hotels, room types, and meal plans","href":"#products","icon":"🗺️"},{"title":"Cache Data Exports","desc":"Sub-millisecond cached hotel rate and availability distribution","href":"#products","icon":"🚀"},{"title":"Resfinity IBE","desc":"High-performance Internet Booking Engine handling 85k+ req/min","href":"#products","icon":"⚡"},{"title":"Yield Optimisation","desc":"Maximize margins dynamically with post-sale hedging rules","href":"#products","icon":"📈"},{"title":"Hotel Extranet","desc":"Direct contracting, allotment management, and rate distribution","href":"#products","icon":"🏨"}]},{"id":"company","label":"Company","items":[{"title":"Selected Customers","desc":"Airtrade, Alltours, Gulf Air, DTA, TripX, Karavel","href":"#customers","icon":"🤝"},{"title":"Partner Testimonials","desc":"What global airline and OTA leaders say about us","href":"#testimonials","icon":"💬"},{"title":"Awards & Recognition","desc":"Magellan Award, Forbes Diamonds, Deloitte Fast 50","href":"#awards","icon":"🏆"},{"title":"ANIXE in Numbers","desc":"24/7/366 reliability, 70+ engineers, 2.5M+ hotels","href":"#numbers","icon":"📊"}]},{"id":"career_blog","label":"Careers & News","items":[{"title":"Career (Jobs)","desc":"Join our engineering & finance team in Wrocław","href":"#careers","icon":"💼"},{"title":"Latest Blog Posts","desc":"ITB Berlin 2026, Holidaymine integration, New World Travel","href":"#news","icon":"📰"}]}]}},{"id":"hero_anixe","type":"cinematic_hero","data":{"tagline":"PURE IT TRAVEL ENGINEERING COMPANY","title":"Born on the Edge of Travel & Technology","subtitle":"Grown on experiences within the demanding airline and travel industries. We design and build safe, stable, high-performance IT systems for travel players to handle thousands of transactions per minute – that’s our forte!","video_url":"https://vimeo.com/76979871","video_provider":"vimeo","video_id":"76979871","showreel_url":"https://vimeo.com/76979871","cta_text":"Get in Touch","cta_target":"#contact","cta_secondary_text":"Explore Solutions","cta_secondary_target":"#solutions"}},{"id":"solutions","type":"services_list","data":{"heading":"Solutions we provide","subheading":"Standardized and bespoke technology ecosystems built for airlines, global tour operators, and high-traffic OTAs","items":[{"title":"Airlines","desc":"With over 20 years of experience in the airline industry, we have covered the entire spectrum. From web based booking engines to mid/back office and mobile apps.","details":"Customizable flight & dynamic packaging engines, FFP loyalty integration, and high-availability enterprise architecture.","price":"Enterprise SLA","duration":"Custom Deployment"},{"title":"Tour Operators","desc":"Our standardized product arsenal is heavily geared towards tour operators. Our agency portal, cache data conversion & export, accelerated search responses, yield optimization service, price buffering, automated mapping and vast third party hotel content all deliver against varying tour operator needs.","details":"Sub-50ms search cache, offline rate feeds in OTDS/JSON/XML, dynamic packaging, and unified supplier distribution.","price":"SaaS Platform","duration":"Full Integration"},{"title":"Online Travel Agencies","desc":"Over the years we have catered to some of the world''s most renowned European OTAs. Providing 3rd party hotel content, managing their loads and infrastructures and delivering sub-second response times are a few of the services we offer.","details":"Aggregated connectivity to 500+ hotel wholesalers, real-time load management, and algorithmic room mapping.","price":"High Volume API","duration":"Scalable Cloud"}]}},{"id":"products","type":"key_features","data":{"heading":"What we do","subheading":"Resfinity modular travel technology suite powering global distribution","items":[{"title":"Hotel Dynamic Sourcing","desc":"More destinations, more hotels, better prices... and therefore higher profit. Open up new horizons and better prospects for your travel business with Resfinity.","icon":"globe"},{"title":"Hotel, Room Type & Meal Mapping","desc":"Automated AI mapping algorithms that eliminate booking errors, standardize rooms across suppliers, and increase bookability.","icon":"check"},{"title":"Cache Data Exports & Search Accelerators","desc":"Resfinity''s hotel price and availability caching system delivers fresh cached data directly to your servers with sub-second response times.","icon":"zap"},{"title":"Internet Booking Engines (Resfinity IBE)","desc":"High-conversion web booking engines designed to handle extreme traffic peaks and multi-currency transactions without slowdown.","icon":"bolt"},{"title":"Yield Optimisation & Price Buffering","desc":"Dynamic profit margin management, post-sale rate optimization, and automated hedging rules to maximize your bottom-line.","icon":"chart"},{"title":"Hotel Extranet & Allotments","desc":"Direct contracting, allotment management, and rate distribution empowering hoteliers and DMCs to control their channel inventory.","icon":"shield"}]}},{"id":"testimonials","type":"testimonials_grid","data":{"heading":"What our partners say about us","items":[{"name":"Ali Jassim","role":"Manager E-Business, Gulf Air – Sales & Marketing","avatar":"https://images.ctfassets.net/13indbtdj8hn/2LXOguhkuy8uRbBuANARTS/5ba92aed74801dfd9de215e4885e2fee/ali_jassim.jpg","rating":5,"text":"ANIXE came out as clear winners and have formed a great partnership with Gulf Air in providing us with a unique, flexible and customizable booking engine that is used by our corporate and FFP customers. We have found the ANIXE team very committed and responsive to our needs."},{"name":"Ronald Bleeker","role":"VP Product Development & Distribution, Airtrade","avatar":"https://images.ctfassets.net/13indbtdj8hn/2GMOGBexqrVm7jl7diVPKQ/5c6dab1f87781ed21d602fd0c8613e5e/Ronald_last2e.jpg","rating":5,"text":"ANIXE is such a company for us. Based on trust, warmth, openness and friendship, over borders, to the future and beyond."},{"name":"Morten Husby","role":"Founder & CEO of TripX","avatar":"https://images.ctfassets.net/13indbtdj8hn/5cgOzxqC4FtqewvMoO0Yw4/b552d079fc9d440ec5fd08b3bc835876/Morten_black_white2.png","rating":5,"text":"ANIXE has developed cutting-edge travel technology solutions for our business and have proven themselves to be an innovative and best in class partner."},{"name":"Fritz Oberhummer","role":"Global Director, Third-Party Technology Partnerships, Expedia Partner Solutions","avatar":"https://images.ctfassets.net/13indbtdj8hn/8Mrx1PDHh9E11rL9oG7Im/66d3d051d3072e4dc907470d2d2cc2fc/expedia_logo2a.jpg","rating":5,"text":"From a technical point of view, ANIXE offered us the widest variety of integration with hotel providers."},{"name":"Jiří Rippel","role":"Head of Project Department, Invia Group","avatar":"https://images.ctfassets.net/13indbtdj8hn/6P3sEfEu6ceNpU9PgJDoWC/4deb86bb0423fb58b1ee74061b07304d/jiri_rippel_slider.jpg","rating":5,"text":"ANIXE is our long-term supplier of flight booking engine and dynamic packaging tool as well as hotel extranet module. The ANIXE staff is very experienced and it always is a pleasure to work on new projects or developments."},{"name":"Fabio Marongiu","role":"Head of Sales - Southern Europe, Hotelston","avatar":"https://images.ctfassets.net/13indbtdj8hn/5Gctl7hAgRkGAL3rNk1Q2R/123367da9e0ca67d4d836f2035758c18/fabio_hotelston.jpg","rating":5,"text":"Our collaboration with ANIXE started in 2014, and synergies and smooth communication helped since the beginning to build a reliable, trustable, and solid partnership that helped any of our mutual partners to succeed in the tourism business."}]}},{"id":"customers","type":"client_logos_grid","data":{"heading":"Selected Customers","subheading":"Empowering global airline flag-carriers, European tour operators, and leading travel platforms","items":[{"id":"c1","name":"Airtrade","logo_url":"https://images.ctfassets.net/13indbtdj8hn/6pGpKsxWtISXo4IGtacEyL/2062f1b5afdc587df9ab2d73c68355f4/airtrade_logo.jpg","website":"https://airtrade.nl"},{"id":"c2","name":"Alltours","logo_url":"https://images.ctfassets.net/13indbtdj8hn/2QXXRnSeUEA2sMQ8kMMCSM/3c352d4022d98efbe017728af6100e7a/alltours.jpg","website":"https://alltours.de"},{"id":"c3","name":"Dutch Travel Alliance","logo_url":"https://images.ctfassets.net/13indbtdj8hn/2MEUoOdHDiegQmkaqa6oCE/94843159b988f58f63967d23d3290ecb/dta.png","website":"https://dutchtravelalliance.nl"},{"id":"c4","name":"Gulf Air","logo_url":"https://images.ctfassets.net/13indbtdj8hn/5xA0rsLgHeUeO6ASwC0wYI/5c5d0c7dafe72675b6991f58af46c8a3/gf.png","website":"https://gulfair.com"},{"id":"c5","name":"Karavel / Promovacances","logo_url":"https://images.ctfassets.net/13indbtdj8hn/7wv1eBR0AMoo4gymiASskm/159892cd649c3d155d6fe3a33894e6da/karavel.jpg","website":"https://karavel.com"},{"id":"c6","name":"LMX Touristik","logo_url":"https://images.ctfassets.net/13indbtdj8hn/7ItbtsnXBmOilMQGXoEmEj/ddfc02bda4eab7340d5112760b6163c3/lmx_logo.jpg","website":"https://lmx.de"},{"id":"c7","name":"TripX","logo_url":"https://images.ctfassets.net/13indbtdj8hn/58GhVoTn7U6xVmM5SLpFvn/d8d3ce6820accc56e7ff9f34684f8437/3-tripx-anixe.jpg","website":"https://tripx.se"},{"id":"c8","name":"TravelWorld","logo_url":"https://images.ctfassets.net/13indbtdj8hn/373VsJF0qsyg4WkAWASQ4I/c9a2dfed49689bc4b19e94ce2dec1986/travelworld_logo.jpg","website":"https://travelworld.com"}]}},{"id":"numbers","type":"trust_stats","data":{"heading":"ANIXE in numbers","subheading":"Extreme scale, continuous availability, and relentless performance","items":[{"value":"24/7/366","label":"Days a year","desc":"Our systems serve our clients, and our clients'' clients around the clock"},{"value":"70+","label":"Specialists","desc":"Dedicated software engineers growing digital travel & commerce"},{"value":"No. 1","label":"Hotel Cache Data","desc":"Largest supplier of hotel cache data across European markets"},{"value":"2.5 mil+","label":"Unique Hotels","desc":"Aggregated and deduplicated across worldwide supplier networks"},{"value":"85.000+","label":"Requests per min","desc":"High-throughput search and booking engines operating under peak load"}]}},{"id":"news","type":"blog_showcase","data":{"heading":"Latest blog posts","subheading":"Insights, partnerships, industry exhibitions, and team culture","items":[{"id":"post1","title":"First Time IT Leader Workshops at ANIXE","category":"Culture & Leadership","date":"25 SEP 2026","author":"ANIXE Team","cover_image":"https://images.ctfassets.net/13indbtdj8hn/ZnySxqdJ8jaEG108OAV0O/f43ba64791a50f18dd38f866ba1655af/image__8_.png?w=600&h=300&fit=thumb","excerpt":"Leadership is learned through conversations, practice, reflection, and real-life challenges. That was the idea behind the two-day First Time IT Leader workshop delivered by Just Results in our office!","content":"Leadership is learned through conversations, practice, reflection, and real-life challenges. That was the idea behind the two-day First Time IT Leader workshop delivered by Just Results in our office!\n\nDuring intense interactive sessions, our newly minted engineering leaders explored practical frameworks for delegation, giving constructive feedback, conflict resolution, and aligning tech delivery with commercial goals."},{"id":"post2","title":"Holidaymine joins ANIXE ecosystem","category":"Partnerships","date":"03 JUN 2026","author":"Product & Sourcing Team","cover_image":"https://images.ctfassets.net/13indbtdj8hn/4BU6cmIdZjRZ9vtlkRE0F1/d7569e7cbc69fc7bda607703b3a7720d/pexels-gokhan-sen-239929248-12268035.jpg?w=600&h=300&fit=thumb","excerpt":"We are pleased to announce the integration of Holidaymine as a new supplier within the ANIXE ecosystem, ensuring a smooth, stable, and scalable connection for B2B distribution.","content":"We are pleased to announce the integration of Holidaymine as a new supplier within the ANIXE ecosystem, ensuring a smooth, stable, and scalable connection for B2B distribution.\n\nHolidaymine''s vast direct hotel inventory is now seamlessly accessible to all Resfinity clients, mapped with sub-second accuracy and automated yield controls."},{"id":"post3","title":"New World Travel Joins the ANIXE Platform","category":"Global Expansion","date":"02 APR 2026","author":"Business Development","cover_image":"https://images.ctfassets.net/13indbtdj8hn/5zcNh9dsVBtRTDCo6i3IiO/e0f931f8292045680b07146e87bd7b34/pexels-igor-passchier-111147847-27507144.jpg?w=600&h=300&fit=thumb","excerpt":"ANIXE is excited to announce the addition of New World Travel (NWT) to our supplier portfolio – a strategic expansion that strengthens our North American offering.","content":"ANIXE is excited to announce the addition of New World Travel (NWT) to our supplier portfolio – a strategic expansion that strengthens our North American offering and brings even greater destination depth to our global client base.\n\nThis partnership provides European and global tour operators with unexcelled rates on US and Canadian hotel properties with automated mapping verification."},{"id":"post4","title":"ANIXE at ITB Berlin 2026 – Innovation, Insights & New Connections","category":"Events & Exhibitions","date":"12 MAR 2026","author":"Zarząd ANIXE","cover_image":"https://images.ctfassets.net/13indbtdj8hn/74M0nGDH335BVkzACdycjQ/af1fe06d2d1b266890dca5171dc8a2f3/14421.jpg?w=600&h=300&fit=thumb","excerpt":"We’ve just wrapped up an inspiring few days at ITB Berlin 2026, and what an event it has been! For ANIXE, ITB is always more than a conference.","content":"We’ve just wrapped up an inspiring few days at ITB Berlin 2026, and what an event it has been! For ANIXE, ITB is always more than a conference.\n\nMeeting hundreds of partners, demonstrating the latest Resfinity search speed benchmarks, and discussing the future of AI-driven hotel mapping proved once again that our technical edge remains unmatched."}]}},{"id":"careers","type":"careers_board","data":{"heading":"Join Us","subheading":"We’re always open to talk to anyone interested in what we do.","intro_text":"There’s a multitude of positions you might be interested in. So have a look at our listings and even if they don’t fit your profile - just call and say Hi. Maybe we can work something out together.","apply_email":"career@anixe.pl","items":[{"id":"job1","title":"Samodzielna Księgowa / Samodzielny Księgowy","department":"Finance & Administration","location":"Wrocław, Poland (Biuro Grabiszyńska)","type":"Pełny etat","salary":"Atrakcyjne wynagrodzenie B2B / UoP","description":"Samodzielne prowadzenie pełnej księgowości spółki technologicznej, rozliczenia podatkowe CIT/VAT oraz raportowanie zarządcze.","requirements":"Doświadczenie w pełnej księgowości, znajomość przepisów podatkowych, mile widziana znajomość specyfiki branży IT / SaaS."},{"id":"job2","title":"Senior C# / .NET Software Engineer (Resfinity IBE)","department":"Core Platform Engineering","location":"Wrocław · Hybrid / Remote","type":"Pełny etat","salary":"18 000 – 26 000 PLN B2B","description":"Projektowanie i optymalizacja wysokowydajnych silników rezerwacji hotelowych przetwarzających ponad 85 000 zapytań na minutę.","requirements":"5+ lat komercyjnego doświadczenia w C#/.NET, znajomość wielowątkowości, architektur rozproszonych i optymalizacji pamięci."},{"id":"job3","title":"Cloud DevOps & High-Load Reliability Engineer","department":"Infrastructure & Reliability","location":"Wrocław / Remote","type":"Pełny etat","salary":"20 000 – 28 000 PLN B2B","description":"Utrzymanie i skalowanie globalnej infrastruktury chmurowej 24/7/366 o rygorystycznym SLA 99.99%.","requirements":"Kubernetes, Docker, monitoring Prometheus/Grafana, automatyzacja CI/CD, optymalizacja kosztów chmury i routing ruchu."},{"id":"job4","title":"Hotel Dynamic Sourcing & Integration Specialist","department":"Product & Partnerships","location":"Wrocław / Remote","type":"Pełny etat","salary":"Konkurencyjne B2B","description":"Zarządzanie integracjami z dostawcami hotelowymi (bedbanks, wholesalers) oraz optymalizacja mapowania pokoi i stawek.","requirements":"Znajomość branży travel tech, standardów XML/JSON API hotelowych, analityczny umysł i biegły angielski."}]}},{"id":"awards","type":"awards_strip","data":{"heading":"Awards & Industry Recognition","items":[{"name":"Travel Weekly Magellan Award","desc":"Overall Travel Technology Provider of the Year — Gold Award winner"},{"name":"Eastern European Business Elite Award","desc":"Best Bespoke Software Development Company in Travel Tech"},{"name":"Deloitte Fast 50 Central Europe","desc":"Recognized among the fastest growing technology enterprises in Central Europe"},{"name":"Business Gazelle Award 2020","desc":"Distinction for financial dynamic growth, business transparency, and reliability"},{"name":"Forbes Diamond Award 2019","desc":"Honored by Forbes among the fastest organically growing technology companies in Poland"},{"name":"Travel & Hospitality Award 2020","desc":"Winner in Technology & Innovation for hotel caching and distribution systems"}]}},{"id":"contact","type":"b2b_lead_scheduler","data":{"heading":"Contact Us & Book a Demo","subheading":"Discuss how Resfinity can accelerate your travel business or schedule a live platform walkthrough with our engineering leadership.","email":"sales@anixe.pl","phone":"+48 71 364 79 50","address":"ul. Grabiszyńska 241b, 53-234 Wrocław, Poland","booking_url":"https://outlook.office365.com/book/anixe@anixe.pl/","booking_cta_text":"Schedule a 30-min Technical Demo (Bookings with Me)","form_heading":"Send an Inquiry to Sales Engineering","form_button_text":"Send Inquiry to sales@anixe.pl","notification_email":"sales@anixe.pl"}},{"id":"footer","type":"simple_footer","data":{"quote":"ANIXE — Growing Digital Travel & Commerce. Over 20 years of bespoke travel engineering.","copyright":"© 2026 ANIXE Polska Sp. z o.o. All rights reserved. Registered in Wrocław, Poland.","privacy_url":"#contact"}}]}}'::jsonb,
